#!/usr/bin/env node
"use strict";

/*
 * run-claude-helper.cjs
 *
 * Runs `.claude/helpers/<name>` with the remaining arguments, or does nothing
 * when that helper is not there. `.claude/helpers/` is claude-flow scaffolding,
 * gitignored and regenerated by `npx ruflo@latest init`, so a fresh clone or a
 * cloud session has none of it. Calling `node .claude/helpers/x.cjs` directly
 * from a hook then fails with "Cannot find module" on every tool call.
 *
 * Usage (from .claude/settings.json):
 *   node "${CLAUDE_PROJECT_DIR:-.}/scripts/run-claude-helper.cjs" hook-handler.cjs pre-bash
 *
 * A missing helper is a silent exit 0. A present helper gets stdin, stdout and
 * stderr untouched and its exit status is passed through. This is plain node,
 * so it behaves the same under sh, cmd and PowerShell.
 */

const { existsSync } = require("node:fs");
const path = require("node:path");
const { spawnSync } = require("node:child_process");

const root = process.env.CLAUDE_PROJECT_DIR || path.resolve(__dirname, "..");
const [name, ...args] = process.argv.slice(2);

// A bare file name only: no separators, no traversal out of .claude/helpers.
if (!name || name !== path.basename(name) || name.startsWith(".")) process.exit(0);

const helper = path.join(root, ".claude", "helpers", name);
if (!existsSync(helper)) process.exit(0);

const result = spawnSync(process.execPath, [helper, ...args], { stdio: "inherit" });
process.exit(result.status ?? 1);
